// Zero dependencies. Data lives in server/db.json. Same routes as the in-browser mock API.
const http = require('http'), fs = require('fs'), path = require('path'), crypto = require('crypto');
const ROOT = path.join(__dirname, '..'), DB = path.join(__dirname, 'db.json');
